// The phone console draws the same persona busts as the desktop (CLOUD.md §13.2, VOICE.md §5.4) without shipping
// React: the desktop's own Bust is rendered here, per persona, into plain SVG data in src/cloud/console/busts.gen.ts.
// This test fails when the drawing changes and the generated file was not refreshed:
//   UPDATE_BUSTS=1 npx vitest run src/renderer/src/components/cloud/consoleBusts.test.ts
import fs from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import type { ReactElement, ReactNode } from 'react'
import { PERSONAS, lookFor } from '@shared/personas'
import { Bust } from '../roman/Bust'

interface BustNode { t: string; a: Record<string, string>; c?: BustNode[] }
const SIZE = 36
const GEN = path.join(__dirname, '../../../../cloud/console/busts.gen.ts')

const kebab = (k: string): string => (k === 'viewBox' || k.startsWith('data-') || k.startsWith('aria-') ? k : k.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`))
function toNodes(el: ReactNode): BustNode[] {
  if (el === null || el === undefined || el === false || el === true) return []
  if (Array.isArray(el)) return el.flatMap(toNodes)
  if (typeof el !== 'object') return []
  const e = el as ReactElement<Record<string, unknown>>
  if (typeof e.type === 'function') return toNodes((e.type as (p: unknown) => ReactNode)(e.props))
  if (typeof e.type !== 'string') return toNodes(e.props.children as ReactNode)
  const a: Record<string, string> = {}
  for (const [k, v] of Object.entries(e.props)) {
    if (k === 'children' || v === undefined || v === null || v === false) continue
    if (k === 'style') for (const [sk, sv] of Object.entries(v as Record<string, unknown>)) a[kebab(sk)] = String(sv)
    else if (k === 'className') a.class = String(v)
    else if (k !== 'width' && k !== 'height') a[kebab(k)] = String(v)
  }
  const c = toNodes(e.props.children as ReactNode)
  return [{ t: e.type, a, ...(c.length ? { c } : {}) }]
}

export function consoleBusts(): Record<string, BustNode> {
  const out: Record<string, BustNode> = {}
  for (const def of PERSONAS) out[def.name] = toNodes(Bust({ look: lookFor(def, def.name), size: SIZE, ring: true }))[0]!
  return out
}

const source = (busts: Record<string, BustNode>): string =>
  `// Generated by src/renderer/src/components/cloud/consoleBusts.test.ts from the desktop's Bust (VOICE.md §5.4). Do not
// edit: UPDATE_BUSTS=1 npx vitest run src/renderer/src/components/cloud/consoleBusts.test.ts
/* eslint-disable */
export interface BustNode { t: string; a: Record<string, string>; c?: BustNode[] }
export const BUST_SIZE = ${SIZE}
export const BUSTS: Record<string, BustNode> = ${JSON.stringify(busts)}
`

describe('console busts', () => {
  it('src/cloud/console/busts.gen.ts is the desktop Bust of every persona, as plain SVG data', () => {
    const want = source(consoleBusts())
    if (process.env.UPDATE_BUSTS) fs.writeFileSync(GEN, want)
    expect(fs.readFileSync(GEN, 'utf8')).toBe(want)
  })

  it('white hairline strokes only: no fill, no colour, no gradient, no event attribute', () => {
    const busts = consoleBusts()
    expect(Object.keys(busts)).toEqual(PERSONAS.map((p) => p.name))
    const attrs: [string, string][] = []
    const walk = (n: BustNode): void => {
      for (const kv of Object.entries(n.a)) attrs.push(kv)
      n.c?.forEach(walk)
    }
    Object.values(busts).forEach(walk)
    expect(new Set(Object.values(busts).map((b) => `${b.a.stroke} ${b.a.fill}`))).toEqual(new Set(['#fff none']))
    expect(attrs.filter(([k]) => /^on/i.test(k))).toEqual([])
    expect(attrs.filter(([k, v]) => /^(fill|stroke|color|stop-color)$/.test(k) && !['none', '#fff'].includes(v))).toEqual([])
    expect(attrs.filter(([, v]) => /gradient|script|url\(/i.test(v))).toEqual([])
  })
})
